Declare Scope i_scope.
Notation "a + b" := (PrimInt63.add a b) : i_scope.
Notation "a - b" := (PrimInt63.sub a b) : i_scope.
Notation "a * b" := (PrimInt63.mul a b) : i_scope.
Notation "a / b" := (PrimInt63.div a b) : i_scope.
Notation "a =? b" := (PrimInt63.eqb a b) : i_scope.
Notation "a <? b" := (PrimInt63.ltb a b) : i_scope.
Local Open Scope uint63_scope.
Local Open Scope i_scope.
Definition nR := Tbl.nR.
Definition FF : int := 12 * nR.
Definition si (s : Sym) : int := match s with S0 => 0 | S1 => 1 end.
Definition qi (q : Q) : int := match q with A => 0 | B => 1 | C => 2 | D => 3 | E => 4 | F => 5 end.
Definition ctl (q : Q) (a : Sym) (r : int) : int := (qi q * 2 + si a) * nR + r.
Definition gs : list int := [0; 1; 2].
Fixpoint rng (n : nat) (i : int) : list int :=
  match n with O => [] | S m => i :: rng m (i + 1) end.
Definition rs : list int := rng (11253)%nat 0.

(* the DFA as an array *)
Fixpoint fill (a : array int) (i : int) (l : list int) : array int * int :=
  match l with [] => (a, i) | x :: l' => fill (PArray.set a i x) (i + 1) l' end.
Fixpoint fills (a : array int) (i : int) (ls : list (list int)) : array int :=
  match ls with
  | [] => a
  | l :: ls' => let '(a', i') := fill a i l in fills a' i' ls'
  end.
Definition mk_d : array int := fills (PArray.make (2 * nR) 0) 0 Tbl.tbl.

(* ---------- saturation, computed in the VM, no proof needed ---------- *)
Record St := mkSt { posts : array (list int); deps : array (list int); ht : array int; hd : array int; wl : list int }.
Definition M1 : int := 4194301.
Definition M2 : int := 4194301.
Definition FF1 : int := FF + 1.
Definition keyt (x g s : int) : int := (x * 3 + g) * FF1 + s + 1.
Fixpoint probe (f : nat) (h : array int) (m k i : int) : int :=
  match f with
  | O => i
  | S f' =>
    let v := PArray.get h i in
    if v =? 0 then i else if v =? k then i else
    probe f' h m k (let j := i + 1 in if j =? m then 0 else j)
  end.
Definition pf : nat := 4000%nat.
Definition add_t (st : St) (x g s : int) : St :=
  let k := keyt x g s in
  let i := probe pf (ht st) M1 k (PrimInt63.mod k M1) in
  if PArray.get (ht st) i =? k then st
  else mkSt (posts st) (deps st) (PArray.set (ht st) i k) (hd st) (k :: wl st).
Definition add_dep (st : St) (s p : int) : St :=
  let k := s * FF1 + p + 1 in
  let i := probe pf (hd st) M2 k (PrimInt63.mod k M2) in
  if PArray.get (hd st) i =? k then st
  else mkSt (posts st) (PArray.set (deps st) s (p :: PArray.get (deps st) s)) (ht st) (PArray.set (hd st) i k) (wl st).
Definition proc (rr lb : array (list int)) (st : St) (k : int) : St :=
  let k1 := k - 1 in
  let s := PrimInt63.mod k1 FF1 in
  let xg := k1 / FF1 in
  let x := xg / 3 in
  let g := PrimInt63.mod xg 3 in
  let st := mkSt (PArray.set (posts st) xg (s :: PArray.get (posts st) xg)) (deps st) (ht st) (hd st) (wl st) in
  let st := if g <? 2 then
      fold_left (fun st p =>
        let st := add_dep st s p in
        let st := fold_left (fun st s2 => add_t st p 0 s2) (PArray.get (posts st) (s * 3)) st in
        let st := fold_left (fun st s2 => add_t st p 1 s2) (PArray.get (posts st) (s * 3 + 1)) st in
        fold_left (fun st s2 => add_t st p 2 s2) (PArray.get (posts st) (s * 3 + 2)) st)
        (PArray.get rr (x * 2 + g)) st
    else st in
  let st := fold_left (fun st p => add_t st p g s) (PArray.get (deps st) x) st in
  if g =? 2 then fold_left (fun st p => add_t st p 2 s) (PArray.get lb x) st else st.
Definition step1 (rr lb : array (list int)) (st : St) : St :=
  match wl st with
  | [] => st
  | k :: w => proc rr lb (mkSt (posts st) (deps st) (ht st) (hd st) w) k
  end.
Fixpoint rep (n : nat) (rr lb : array (list int)) (st : St) : St :=
  match wl st with
  | [] => st
  | _ => match n with
         | O => step1 rr lb st
         | S m => rep m rr lb (rep m rr lb st)
         end
  end.
Definition dl (d : array int) (r c : int) : int := PArray.get d (r * 2 + c).
Definition init_one (d : array int) (acc : array (list int) * array (list int) * St) (q : Q) (a : Sym) (r : int)
  : array (list int) * array (list int) * St :=
  let '(rr, lb, st) := acc in
  match tm (q, a) with
  | None =>
    let p := ctl q a r in
    (rr, lb, add_t (add_t (add_t st p 0 FF) p 1 FF) p 2 FF)
  | Some (w, L, q2) =>
    let p := ctl q a r in
    let r3 := dl d r (si w) in
    let st := add_t st p 0 (ctl q2 S0 r3) in
    let st := add_t st p 1 (ctl q2 S1 r3) in
    let i := ctl q2 S0 r3 in
    (rr, PArray.set lb i (p :: PArray.get lb i), st)
  | Some (w, R, q2) =>
    (* r plays the rest of the right tape, b the cell read next *)
    let i0 := ctl q2 S0 r * 2 + si w in
    let i1 := ctl q2 S1 r * 2 + si w in
    let rr := PArray.set rr i0 (ctl q a (dl d r 0) :: PArray.get rr i0) in
    let rr := PArray.set rr i1 (ctl q a (dl d r 1) :: PArray.get rr i1) in
    (rr, lb, st)
  end.
Definition saturate (d : array int) : array (list int) :=
  let st0 := mkSt (PArray.make (3 * FF1) []) (PArray.make FF1 []) (PArray.make M1 0) (PArray.make M2 0) [] in
  let st0 := add_t (add_t (add_t st0 FF 0 FF) FF 1 FF) FF 2 FF in
  let a0 := (PArray.make (2 * FF1) [], PArray.make FF1 [], st0) in
  let a1 := fold_left (fun acc q => fold_left (fun acc a => fold_left (fun acc r => init_one d acc q a r) rs acc) all_syms acc) all_qs a0 in
  let '(rr, lb, st) := a1 in
  posts (rep 24%nat rr lb st).

(* ---------- the proof ---------- *)
Fixpoint lf (xs : list Sym) : Stream Sym :=
  match xs with [] => const s0 | x :: xs' => Cons x (lf xs') end.
Definition Cfg : Type := (Q * list Sym * Sym * list Sym)%type.
Definition lift (c : Cfg) : Q * tape :=
  match c with (q, l, a, r) => (q, (lf l, a, lf r)) end.
Definition cstep (c : Cfg) : option Cfg :=
  match c with
  | (q, l, a, r) =>
    match tm (q, a) with
    | None => None
    | Some (w, L, q2) =>
      match l with
      | [] => Some (q2, [], S0, w :: r)
      | b :: l' => Some (q2, l', b, w :: r)
      end
    | Some (w, R, q2) =>
      match r with
      | [] => Some (q2, w :: l, S0, [])
      | b :: r' => Some (q2, w :: l, b, r')
      end
    end
  end.
Lemma cstep_ok c c' : cstep c = Some c' -> lift c -[ tm ]-> lift c'.
Proof.
  destruct c as [[[q l] a] r]. unfold cstep.
  destruct (tm (q, a)) as [[[w d0] q2]|] eqn:Ht; intros H; [|discriminate].
  destruct d0.
  - destruct l as [|b l']; injection H as <-; exact (step_left Ht).
  - destruct r as [|b r']; injection H as <-; exact (step_right Ht).
Qed.
Fixpoint runn (n : nat) (c : Cfg) : option Cfg :=
  match n with
  | O => Some c
  | S m => match cstep c with None => None | Some c' => runn m c' end
  end.
Lemma runn_ok n c c' : runn n c = Some c' -> lift c -[ tm ]->* lift c'.
Proof.
  revert c. induction n as [|m IH]; intros c H; simpl in H.
  - injection H as <-. apply evstep_refl.
  - destruct (cstep c) as [c1|] eqn:E; [|discriminate].
    eapply evstep_step; [apply cstep_ok; exact E | apply IH; exact H].
Qed.
Definition start_cfg : Cfg := (A, [], S0, []).

Fixpoint inb (s : int) (l : list int) : bool :=
  match l with
  | [] => false
  | t :: l' => if s =? t then true else inb s l'
  end.
Lemma inb_In s l : inb s l = true <-> In s l.
Proof.
  induction l as [|t l IH]; simpl.
  - split; [discriminate | tauto].
  - destruct (s =? t) eqn:E.
    + apply Uint63.eqb_spec in E. subst. split; [auto | reflexivity].
    + rewrite IH. split; [auto |].
      intros [H|H]; [|exact H].
      exfalso. rewrite H in E. assert (Hss : (s =? s) = true) by (apply Uint63.eqb_spec; reflexivity).
      rewrite Hss in E. discriminate.
Qed.

Section Sound.
Variables (d : array int) (P : array (list int)) (rs0 : list int).
Definition delta (r c : int) : int := PArray.get d (r * 2 + c).
Definition post (x g : int) : list int := PArray.get P (x * 3 + g).
Fixpoint rst (r : list Sym) : int :=
  match r with [] => 0 | x :: xs => delta (rst xs) (si x) end.
Fixpoint acc (p : int) (l : list Sym) : bool :=
  match l with
  | [] => inb FF (post p 2)
  | b :: l' => existsb (fun s => acc s l') (post p (si b))
  end.
Definition chk_r (q : Q) (a : Sym) (r : int) : bool :=
  match tm (q, a) with
  | None => forallb (fun g => inb FF (post (ctl q a r) g)) gs
  | Some (w, L, q2) =>
    inb (ctl q2 S0 (delta r (si w))) (post (ctl q a r) 0)
    && inb (ctl q2 S1 (delta r (si w))) (post (ctl q a r) 1)
    && forallb (fun s => inb s (post (ctl q a r) 2)) (post (ctl q2 S0 (delta r (si w))) 2)
  | Some (w, R, q2) =>
    forallb (fun b =>
      forallb (fun s0 =>
        forallb (fun g =>
          forallb (fun s => inb s (post (ctl q a (delta r (si b))) g)) (post s0 g)) gs)
        (post (ctl q2 b r) (si w)))
      all_syms
  end.
Definition SS : nat := 1000%nat.
Definition start_ok : bool :=
  match runn SS start_cfg with
  | Some (q, l, a, r) => negb (acc (ctl q a (rst r)) l)
  | None => false
  end.
Definition check_all : bool :=
  (delta 0 0 =? 0)
  && inb 0 rs0
  && forallb (fun r => inb (delta r 0) rs0 && inb (delta r 1) rs0) rs0
  && forallb (fun g => inb FF (post FF g)) gs
  && forallb (fun q => forallb (fun a => forallb (chk_r q a) rs0) all_syms) all_qs
  && start_ok.

Hypothesis Hall : check_all = true.

Let H6 : start_ok = true.
Proof. unfold check_all in Hall. apply andb_prop in Hall as [_ H]. exact H. Qed.
Let H5 : forall q a r, In r rs0 -> chk_r q a r = true.
Proof.
  unfold check_all in Hall. apply andb_prop in Hall as [H _]. apply andb_prop in H as [_ H].
  rewrite forallb_forall in H. intros q a r Hr.
  specialize (H q (all_qs_spec q)). rewrite forallb_forall in H.
  specialize (H a (all_syms_spec a)). rewrite forallb_forall in H. exact (H r Hr).
Qed.
Let H4 : forall g, In g gs -> In FF (post FF g).
Proof.
  unfold check_all in Hall. apply andb_prop in Hall as [H _]. apply andb_prop in H as [H _].
  apply andb_prop in H as [_ H]. rewrite forallb_forall in H.
  intros g Hg. apply inb_In. exact (H g Hg).
Qed.
Let H3 : forall r, In r rs0 -> In (delta r 0) rs0 /\ In (delta r 1) rs0.
Proof.
  unfold check_all in Hall. apply andb_prop in Hall as [H _]. apply andb_prop in H as [H _].
  apply andb_prop in H as [H _]. apply andb_prop in H as [_ H]. rewrite forallb_forall in H.
  intros r Hr. specialize (H r Hr). apply andb_prop in H as [H1 H2].
  apply inb_In in H1, H2. split; assumption.
Qed.
Let H2 : In 0 rs0.
Proof.
  unfold check_all in Hall. apply andb_prop in Hall as [H _]. apply andb_prop in H as [H _].
  apply andb_prop in H as [H _]. apply andb_prop in H as [H _]. apply andb_prop in H as [_ H].
  apply inb_In. exact H.
Qed.
Let H1 : delta 0 0 = 0.
Proof.
  unfold check_all in Hall. apply andb_prop in Hall as [H _]. apply andb_prop in H as [H _].
  apply andb_prop in H as [H _]. apply andb_prop in H as [H _]. apply andb_prop in H as [H _].
  apply Uint63.eqb_spec. exact H.
Qed.

Lemma rst_valid r : In (rst r) rs0.
Proof.
  induction r as [|x xs IH].
  - exact H2.
  - destruct x; simpl; apply H3 in IH; destruct IH as [Ha Hb]; assumption.
Qed.
Lemma si_gs b : In (si b) gs.
Proof. destruct b; simpl; auto. Qed.
Lemma acc_FF l : acc FF l = true.
Proof.
  induction l as [|b l IH]; simpl.
  - apply inb_In. apply H4. simpl. auto.
  - apply existsb_exists. exists FF. split; [apply H4, si_gs | exact IH].
Qed.
Lemma lf_uncons r : exists b r', lf r = Cons b (lf r') /\ rst r = delta (rst r') (si b).
Proof.
  destruct r as [|b r'].
  - exists S0, (@nil Sym). split.
    + simpl. apply const_unfold.
    + simpl. symmetry. exact H1.
  - exists b, r'. split; reflexivity.
Qed.

Definition Inv (c : Q * tape) : Prop :=
  exists q l a r, c = (q, (lf l, a, lf r)) /\ acc (ctl q a (rst r)) l = false.

Lemma step_inv c : Inv c -> exists c', Inv c' /\ c -[ tm ]->+ c'.
Proof.
  intros [q [l [a [r [-> Hg]]]]].
  destruct (tm (q, a)) as [[[w d0] q2]|] eqn:Ht.
  - destruct d0.
    + pose proof (H5 q a (rst r) (rst_valid r)) as Hc.
      unfold chk_r in Hc. rewrite Ht in Hc.
      apply andb_prop in Hc as [Hc Hc3]. apply andb_prop in Hc as [Hc1 Hc2].
      apply inb_In in Hc1, Hc2. rewrite forallb_forall in Hc3.
      destruct l as [|b l'].
      * exists (q2, (lf (@nil Sym), S0, lf (w :: r))). split.
        -- exists q2, (@nil Sym), S0, (w :: r). split; [reflexivity|].
           destruct (acc (ctl q2 S0 (rst (w :: r))) []) eqn:E; [|reflexivity].
           exfalso. simpl in E. apply inb_In in E.
           specialize (Hc3 _ E). simpl in Hg. rewrite Hc3 in Hg. discriminate.
        -- apply progress_base. exact (step_left Ht).
      * exists (q2, (lf l', b, lf (w :: r))). split.
        -- exists q2, l', b, (w :: r). split; [reflexivity|].
           destruct (acc (ctl q2 b (rst (w :: r))) l') eqn:E; [|reflexivity].
           exfalso. simpl in Hg.
           assert (Hw : existsb (fun s => acc s l') (post (ctl q a (rst r)) (si b)) = true).
           { apply existsb_exists. exists (ctl q2 b (delta (rst r) (si w))). split.
             - destruct b; assumption.
             - exact E. }
           rewrite Hw in Hg. discriminate.
        -- apply progress_base. exact (step_left Ht).
    + destruct (lf_uncons r) as [b [r' [Er Erst]]].
      pose proof (H5 q a (rst r') (rst_valid r')) as Hc.
      unfold chk_r in Hc. rewrite Ht in Hc. rewrite forallb_forall in Hc.
      specialize (Hc b (all_syms_spec b)). rewrite <- Erst in Hc.
      rewrite forallb_forall in Hc.
      exists (q2, (lf (w :: l), b, lf r')). split.
      * exists q2, (w :: l), b, r'. split; [reflexivity|].
        destruct (acc (ctl q2 b (rst r')) (w :: l)) eqn:E; [|reflexivity].
        exfalso. simpl in E. apply existsb_exists in E as [s0 [Hs0 Has0]].
        specialize (Hc s0 Hs0). rewrite forallb_forall in Hc.
        destruct l as [|g l'].
        -- simpl in Has0. apply inb_In in Has0.
           assert (Hg2 : In 2 gs) by (simpl; auto).
           specialize (Hc 2 Hg2). rewrite forallb_forall in Hc. specialize (Hc _ Has0).
           simpl in Hg. rewrite Hc in Hg. discriminate.
        -- simpl in Has0. apply existsb_exists in Has0 as [s [Hs Has]].
           specialize (Hc (si g) (si_gs g)). rewrite forallb_forall in Hc.
           specialize (Hc _ Hs). apply inb_In in Hc.
           simpl in Hg.
           assert (Hw : existsb (fun s => acc s l') (post (ctl q a (rst r)) (si g)) = true).
           { apply existsb_exists. exists s. split; assumption. }
           rewrite Hw in Hg. discriminate.
      * apply progress_base. rewrite Er. exact (step_right Ht).
  - exfalso.
    pose proof (H5 q a (rst r) (rst_valid r)) as Hc.
    unfold chk_r in Hc. rewrite Ht in Hc. rewrite forallb_forall in Hc.
    destruct l as [|b l'].
    + assert (Hg2 : In 2 gs) by (simpl; auto).
      specialize (Hc 2 Hg2). simpl in Hg. rewrite Hc in Hg. discriminate.
    + simpl in Hg.
      assert (Hw : existsb (fun s => acc s l') (post (ctl q a (rst r)) (si b)) = true).
      { apply existsb_exists. exists FF. split.
        - apply inb_In. apply Hc. apply si_gs.
        - apply acc_FF. }
      rewrite Hw in Hg. discriminate.
Qed.

Theorem sound : ~ halts tm c0.
Proof.
  pose proof H6 as H6'. unfold start_ok in H6'.
  destruct (runn SS start_cfg) as [[[[q l] a] r]|] eqn:Er; [|discriminate].
  apply negb_true_iff in H6'.
  change c0 with (lift start_cfg).
  eapply multistep_nonhalt.
  - apply runn_ok with (n := SS). exact Er.
  - apply progress_nonhalt with (P := Inv).
    + apply step_inv.
    + exists q, l, a, r. split; [reflexivity | exact H6'].
Qed.
End Sound.

Theorem nonhalt : ~ halts tm c0.
Proof.
  apply (sound mk_d (saturate mk_d) rs).
  vm_cast_no_check (eq_refl true).
Time Qed.

End TM1.
Print Assumptions TM1.nonhalt.
